## 4. Tool API

### 4.1 Tool 基类

```cpp
class Tool {
public:
  // 虚析构函数
  virtual ~Tool() = default;

  // 获取 Tool 名称
  // 返回：std::string - Tool 名称
  virtual std::string getName() const = 0;

  // 获取 Tool 描述
  // 返回：std::string - Tool 描述
  virtual std::string getDescription() const = 0;

  // 获取 Tool 定义
  // 返回：json - Tool 定义
  virtual json getToolDefinitions() const = 0;

  // 执行 Tool
  // 参数：params - 输入参数
  // 返回：json - 执行结果
  virtual json execute(const json& params) = 0;

  // 验证参数
  // 参数：params - 输入参数
  // 返回：bool - 参数是否有效
  virtual bool validateParams(const json& params) const = 0;

  // 获取错误信息
  // 返回：std::string - 错误信息
  virtual std::string getLastError() const = 0;
};
```

