## 5. 传感器 API

### 5.1 SensorService 类

```cpp
class SensorService {
public:
  // 初始化传感器服务
  void init();

  // 注册传感器
  // 参数：config - 传感器配置
  void registerSensor(const SensorConfig& config);

  // 读取传感器数据
  // 参数：sensor_id - 传感器 ID
  // 返回：SensorData - 传感器数据
  SensorData readSensor(const std::string& sensor_id);

  // 批量读取
  // 参数：sensor_ids - 传感器 ID 列表
  // 返回：std::vector<SensorData> - 传感器数据列表
  std::vector<SensorData> readSensors(const std::vector<std::string>& sensor_ids);

  // 设置采样率
  // 参数：sensor_id - 传感器 ID
  //        rate - 采样率（Hz）
  void setSampleRate(const std::string& sensor_id, int rate);

  // 启用/禁用传感器
  // 参数：sensor_id - 传感器 ID
  //        enable - 是否启用
  void enableSensor(const std::string& sensor_id, bool enable);

  // 获取传感器状态
  // 参数：sensor_id - 传感器 ID
  // 返回：SensorStatus - 传感器状态
  SensorStatus getSensorStatus(const std::string& sensor_id);

  // 设置数据回调
  // 参数：sensor_id - 传感器 ID
  //        callback - 回调函数
  void setDataCallback(const std::string& sensor_id, 
                       std::function<void(const SensorData&)> callback);
};
```

