## 6. 音频 API

### 6.1 AudioService 类

```cpp
class AudioService {
public:
  // 初始化音频服务
  void init();

  // 开始录音
  // 参数：sample_rate - 采样率
  //        channels - 声道数
  void startRecording(int sample_rate = 16000, int channels = 1);

  // 停止录音
  // 返回：std::vector<int16_t> - 录音数据
  std::vector<int16_t> stopRecording();

  // 播放音频
  // 参数：data - 音频数据
  //        sample_rate - 采样率
  void playAudio(const std::vector<int16_t>& data, int sample_rate = 16000);

  // 播放提示音
  // 参数：type - 提示音类型
  void playTone(const std::string& type);

  // 设置音量
  // 参数：volume - 音量（0-100）
  void setVolume(int volume);

  // 获取音量
  // 返回：int - 当前音量
  int getVolume();

  // 静音/取消静音
  // 参数：mute - 是否静音
  void setMute(bool mute);

  // 设置音频回调
  // 参数：callback - 回调函数
  void setAudioCallback(std::function<void(const std::vector<int16_t>&)> callback);
};
```

## 7. 蓝牙 API

### 7.1 BLEService 类

```cpp
class BLEService {
public:
  // 初始化蓝牙服务
  void init();

  // 开始广播
  // 参数：device_name - 设备名称
  void startAdvertising(const std::string& device_name);

  // 停止广播
  void stopAdvertising();

  // 连接到设备
  // 参数：address - 设备地址
  // 返回：bool - 是否成功
  bool connect(const std::string& address);

  // 断开连接
  void disconnect();

  // 发送数据
  // 参数：service_uuid - 服务 UUID
  //        characteristic_uuid - 特征 UUID
  //        data - 发送数据
  // 返回：bool - 是否成功
  bool sendData(const std::string& service_uuid,
                const std::string& characteristic_uuid,
                const std::vector<uint8_t>& data);

  // 接收数据
  // 参数：service_uuid - 服务 UUID
  //        characteristic_uuid - 特征 UUID
  //        callback - 回调函数
  void receiveData(const std::string& service_uuid,
                   const std::string& characteristic_uuid,
                   std::function<void(const std::vector<uint8_t>&)> callback);

  // 获取连接状态
  // 返回：bool - 是否已连接
  bool isConnected();

  // 获取设备地址
  // 返回：std::string - 设备地址
  std::string getDeviceAddress();
};
```

## 8. 电源管理 API

### 8.1 PowerManager 类

```cpp
class PowerManager {
public:
  // 初始化电源管理
  void init();

  // 进入休眠模式
  // 参数：mode - 休眠模式
  void enterSleep(SleepMode mode);

  // 唤醒
  void wakeUp();

  // 获取当前电源状态
  // 返回：PowerState - 电源状态
  PowerState getPowerState();

  // 获取电池电量
  // 返回：float - 电量（0-1）
  float getBatteryLevel();

  // 设置唤醒源
  // 参数：source - 唤醒源
  //        enable - 是否启用
  void setWakeSource(WakeSource source, bool enable);

  // 获取唤醒源状态
  // 参数：source - 唤醒源
  // 返回：bool - 是否启用
  bool getWakeSourceStatus(WakeSource source);

  // 设置低电量回调
  // 参数：threshold - 阈值
  //        callback - 回调函数
  void setLowBatteryCallback(float threshold, 
                             std::function<void(float)> callback);
};
```

